// ── Helpers ────────────────────────────────────────────
// Heatmap color: T>=50のみ色付け、50未満は無色
function heatT(t) {
  if (t < 50) return "rgba(255,255,255,0.04)";
  const r = Math.min(1, (t-50)/22);
  return `rgba(200,160,50,${0.18 + r*0.65})`;
}
function fmt(n) { return n.toLocaleString("ja-JP"); }
// T-scoreを0-10スケールに変換（レーダー用、30→0, 70→10）
function t2r(t) { return Math.max(0, Math.min(10, (t-30)/4)); }

// ── V2 helpers ─────────────────────────────────────────
const AREA_CENTERS = Object.fromEntries(AREAS.map(a => [a, SPOTS_DATA[a].c]));
const V2_METRICS = {
  vitality: { label: "Culture Vitality", jp: "文化活力", color: "#E8C864" },
  density: { label: "Density", jp: "集積性", color: "#D4A574" },
  distinctiveness: { label: "Distinctiveness", jp: "固有性", color: "#C58AF9" },
  quality: { label: "Quality", jp: "質", color: "#7EB8C4" },
};

function clamp(v, min=0, max=100) { return Math.max(min, Math.min(max, v)); }
function percentileMap(rawByArea) {
  const vals = AREAS.map(a => rawByArea[a]);
  return Object.fromEntries(AREAS.map(a => {
    const v = rawByArea[a];
    const below = vals.filter(x => x < v).length;
    const equal = vals.filter(x => x === v).length;
    const pct = ((below + (equal - 1) / 2) / Math.max(1, vals.length - 1)) * 100;
    return [a, clamp(pct)];
  }));
}
function calcOverallGenreShare() {
  const totals = Object.fromEntries(GENRES.map(g => [g, 0]));
  AREAS.forEach(a => GENRES.forEach(g => totals[g] += SCORES[a].genre[g].count));
  const sum = Object.values(totals).reduce((a,b)=>a+b,0);
  return Object.fromEntries(GENRES.map(g => [g, totals[g] / sum]));
}
const OVERALL_GENRE_SHARE = calcOverallGenreShare();
function calcLq(area, genre) {
  const s = SCORES[area];
  const areaTotal = GENRES.reduce((sum,g)=>sum+s.genre[g].count,0);
  const areaShare = s.genre[genre].count / areaTotal;
  return areaShare / OVERALL_GENRE_SHARE[genre];
}
function calcDistinctivenessRaw(area) {
  const s = SCORES[area];
  const areaTotal = GENRES.reduce((sum,g)=>sum+s.genre[g].count,0);
  // Jensen-Shannon divergence between area genre mix and Tokyo sample mix.
  let js = 0;
  GENRES.forEach(g => {
    const p = Math.max(1e-9, s.genre[g].count / areaTotal);
    const q = Math.max(1e-9, OVERALL_GENRE_SHARE[g]);
    const m = (p + q) / 2;
    js += 0.5 * p * Math.log(p/m) + 0.5 * q * Math.log(q/m);
  });
  return js;
}
const DENSITY_PCT = percentileMap(Object.fromEntries(AREAS.map(a=>[a,SCORES[a].area.density])));
const QUALITY_PCT = percentileMap(Object.fromEntries(AREAS.map(a=>[a,SCORES[a].area.quality])));
const DISTINCT_PCT = percentileMap(Object.fromEntries(AREAS.map(a=>[a,calcDistinctivenessRaw(a)])));
const V2 = Object.fromEntries(AREAS.map(a => {
  const density = DENSITY_PCT[a];
  const quality = QUALITY_PCT[a];
  const distinctiveness = DISTINCT_PCT[a];
  // Current-data MVP. Dynamism and Momentum are deliberately excluded until time-series/event data exists.
  const vitality = 0.45*density + 0.25*quality + 0.30*distinctiveness;
  return [a,{density,quality,distinctiveness,vitality}];
}));
const V2_RANKED = [...AREAS].sort((a,b)=>V2[b].vitality-V2[a].vitality);

function typeFor(area) {
  const v = V2[area];
  if (v.vitality >= 70 && v.distinctiveness >= 60) return {name:"LEAD", jp:"強みを伸ばす", color:"#E8C864"};
  if (v.vitality >= 70) return {name:"PROTECT", jp:"既存価値を守る", color:"#F0A65A"};
  if (v.distinctiveness >= 60 || v.quality >= 65) return {name:"SEED", jp:"小さく育てる", color:"#80C6A6"};
  return {name:"RETHINK", jp:"別の価値軸を探る", color:"#8590A6"};
}
function strongestDna(area) {
  return GENRES.map(g=>({g,lq:calcLq(area,g)})).sort((a,b)=>b.lq-a.lq);
}
function narrative(area) {
  const v = V2[area];
  const top = strongestDna(area)[0];
  if (v.vitality >= 75 && v.distinctiveness >= 70) return `${top.g}への特化が明確で、文化資源の集積も厚い。現状の強みを毀損せず、更新を支える投資が有効。`;
  if (v.distinctiveness >= 70) return `${top.g}に東京平均を上回る固有性がある。一律な集客投資より、その個性を増幅する小規模施策が向く。`;
  if (v.quality >= 70 && v.density < 60) return `集積量は大きくない一方、質の高い文化資源が存在する。面的な拡張より、既存拠点の接続・発信が有効。`;
  if (v.density >= 70) return `文化資源の量は十分。次の論点は「何がこの街固有なのか」を明確にし、画一化を避けること。`;
  return `現時点では文化集積・固有性ともに限定的。カルチャー施策単独ではなく、生活・商業・公共空間など別の価値軸との組み合わせが必要。`;
}

function metricColor(metric) { return V2_METRICS[metric].color; }
function scoreColor(v, color="#E8C864") {
  const a = 0.12 + clamp(v)/100*0.72;
  return `${color}${Math.round(a*255).toString(16).padStart(2,"0")}`;
}
function barWidth(v){ return `${clamp(v)}%`; }
function shortGenre(g){
  return ({"食文化":"Food","芸術文化":"Art","音楽舞台":"Music","知的文化":"Books","ファッション・D":"Fashion","ナイトタイム":"Night"})[g] || g;
}

function ScrollControl() {
  const map = useMap();
  useEffect(() => {
    map.scrollWheelZoom.disable();
    const enable = () => map.scrollWheelZoom.enable();
    const disable = () => map.scrollWheelZoom.disable();
    map.on("click", enable);
    const outside = e => { if (!map.getContainer().contains(e.target)) disable(); };
    document.addEventListener("click", outside);
    return () => { map.off("click", enable); document.removeEventListener("click", outside); };
  },[map]);
  return null;
}
function MapFly({area, zoom=12}) {
  const map=useMap();
  useEffect(()=>{ map.flyTo(AREA_CENTERS[area],zoom,{duration:0.55}); },[area,zoom,map]);
  return null;
}

function MetricBar({label,value,color,sub}) {
  return <div className="metricBar">
    <div className="metricBarTop"><span>{label}</span><span className="mono" style={{color}}>{value.toFixed(0)}</span></div>
    <div className="track"><div className="fill" style={{width:barWidth(value),background:color}}/></div>
    {sub && <div className="micro muted">{sub}</div>}
  </div>;
}

function DnaBars({area, compact=false}) {
  const dna=strongestDna(area);
  return <div className="dnaBars">
    {dna.map(({g,lq})=>{
      const max=2.2;
      return <div className="dnaRow" key={g}>
        <div className="dnaLabel"><span className="dot" style={{background:GCOL[g]}}/><span>{shortGenre(g)}</span></div>
        <div className="dnaTrack"><div className="dnaFill" style={{width:`${Math.min(100,lq/max*100)}%`,background:GCOL[g]}}/></div>
        <div className="mono dnaVal" style={{color:lq>=1?GCOL[g]:"rgba(255,255,255,.38)"}}>{lq.toFixed(2)}×</div>
      </div>;
    })}
    {!compact && <div className="micro muted" style={{marginTop:8}}>1.00× = 10エリア全体の構成比と同じ。1.00×超ほど、そのジャンルへの特化が強い。</div>}
  </div>;
}

function AreaList({selected,onSelect}) {
  return <div className="areaList">
    {V2_RANKED.map((area,i)=>{
      const active=selected===area;
      const t=typeFor(area);
      const top=strongestDna(area)[0];
      return <button key={area} className={`areaRow ${active?"active":""}`} onClick={()=>onSelect(area)}>
        <div className="rank mono">{String(i+1).padStart(2,"0")}</div>
        <div className="areaRowMain">
          <div className="areaNameLine"><span className="areaName">{area}</span><span className="typePill" style={{borderColor:`${t.color}70`,color:t.color}}>{t.name}</span></div>
          <div className="micro muted">{shortGenre(top.g)} {top.lq.toFixed(2)}× · {SCORES[area].total_spots} spots</div>
        </div>
        <div className="areaScore mono">{V2[area].vitality.toFixed(0)}</div>
      </button>;
    })}
  </div>;
}

function OverviewMap({selected,onSelect,metric}) {
  const c=metricColor(metric);
  return <div className="mapWrap">
    <MapContainer center={[35.68,139.70]} zoom={11} style={{height:"100%",width:"100%"}} scrollWheelZoom={false} zoomControl={true}>
      <TileLayer url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png" attribution='&copy; OpenStreetMap &copy; CARTO' subdomains="abcd" maxZoom={20}/>
      <ScrollControl/>
      <MapFly area={selected} zoom={12}/>
      {AREAS.map(area=>{
        const v=V2[area][metric];
        const isSel=selected===area;
        const radius=8+v/100*13;
        return <CircleMarker key={area} center={AREA_CENTERS[area]} radius={radius}
          pathOptions={{color:isSel?"#fff":c,weight:isSel?2.5:1.2,fillColor:c,fillOpacity:isSel?.92:.58}}
          eventHandlers={{click:()=>onSelect(area)}}>
          <Popup>
            <div style={{minWidth:180,fontFamily:"sans-serif"}}>
              <div style={{fontSize:16,fontWeight:700,marginBottom:6}}>{area}</div>
              <div style={{display:"flex",justifyContent:"space-between",gap:20}}><span>{V2_METRICS[metric].jp}</span><b>{v.toFixed(0)}</b></div>
              <div style={{fontSize:11,opacity:.7,marginTop:5}}>Culture Vitality {V2[area].vitality.toFixed(0)}</div>
            </div>
          </Popup>
        </CircleMarker>;
      })}
    </MapContainer>
    <div className="mapLegend">
      <div className="micro">{V2_METRICS[metric].label}</div>
      <div className="legendScale" style={{background:`linear-gradient(90deg,${c}22,${c})`}}/>
      <div className="legendNums mono"><span>LOW</span><span>HIGH</span></div>
    </div>
  </div>;
}

function CultureSpotMap({area}) {
  const data=SPOTS_DATA[area];
  const center=data.c;
  const [active,setActive]=useState(["f","a","m","i","x","n"]);
  const spots=useMemo(()=>data.s.map((sp,i)=>({idx:i,name:sp[0],gkey:sp[1],rating:sp[2],reviews:sp[3],lat:center[0]+sp[4]/100000,lng:center[1]+sp[5]/100000})),[area]);
  const filters=[["f","食"],["a","芸術"],["m","音楽"],["i","知的"],["x","Fash"],["n","Night"]];
  return <div>
    <div className="spotFilters">
      {filters.map(([k,l])=><button key={k} className="chip" onClick={()=>setActive(p=>p.includes(k)?p.filter(x=>x!==k):[...p,k])} style={{color:active.includes(k)?GKCOL[k]:"rgba(255,255,255,.32)",borderColor:active.includes(k)?`${GKCOL[k]}70`:"rgba(255,255,255,.1)"}}><span className="dot" style={{background:active.includes(k)?GKCOL[k]:"rgba(255,255,255,.2)"}}/>{l}</button>)}
      <span className="micro muted" style={{marginLeft:"auto"}}>{spots.filter(s=>active.includes(s.gkey)).length} spots</span>
    </div>
    <div className="spotMap">
      <MapContainer key={area} center={center} zoom={16} style={{height:"100%",width:"100%"}} scrollWheelZoom={false}>
        <TileLayer url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png" attribution='&copy; OpenStreetMap &copy; CARTO' subdomains="abcd" maxZoom={20}/>
        <ScrollControl/>
        <Circle center={center} radius={500} pathOptions={{color:"#E8C864",fillColor:"#E8C864",fillOpacity:.025,weight:1.5,dashArray:"5,5"}}/>
        {spots.filter(s=>active.includes(s.gkey)).map(sp=><CircleMarker key={sp.idx} center={[sp.lat,sp.lng]} radius={sp.rating>=4.5&&sp.reviews>=300?7:4}
          pathOptions={{color:"#111",weight:1,fillColor:GKCOL[sp.gkey],fillOpacity:.78}}>
          <Popup><div style={{minWidth:170,fontFamily:"sans-serif"}}><div style={{fontSize:10,color:GKCOL[sp.gkey],fontWeight:700}}>{GKEY_MAP[sp.gkey]}</div><div style={{fontSize:14,fontWeight:700,margin:"4px 0"}}>{sp.name}</div><div style={{fontSize:11}}>★ {sp.rating.toFixed(1)} · {fmt(sp.reviews)} reviews</div></div></Popup>
        </CircleMarker>)}
      </MapContainer>
    </div>
  </div>;
}

function AreaDetail({area}) {
  const v=V2[area], t=typeFor(area), top=strongestDna(area)[0];
  return <div className="detailCard">
    <div className="detailHead">
      <div>
        <div className="eyebrow">AREA DIAGNOSIS / CURRENT DATA</div>
        <h2>{area}</h2>
        <div className="detailTagline">{shortGenre(top.g)}に東京平均比 {top.lq.toFixed(2)}× の特化</div>
      </div>
      <div className="vitalBlock">
        <div className="mono vitalNum">{v.vitality.toFixed(0)}</div>
        <div className="micro muted">CULTURE VITALITY / 100</div>
      </div>
    </div>
    <div className="typeBanner" style={{borderColor:`${t.color}55`,background:`${t.color}0F`}}>
      <div><span className="mono" style={{color:t.color,fontWeight:700}}>{t.name}</span><span className="muted"> — {t.jp}</span></div>
      <div className="micro muted">※ Momentum未計測のため、現状値のみからの暫定タイプ</div>
    </div>
    <div className="detailGrid">
      <div className="panel">
        <div className="panelTitle">CURRENT STRUCTURE</div>
        <MetricBar label="Density / 集積性" value={v.density} color={V2_METRICS.density.color} sub="既存T-Scoreの密度を10エリア内パーセンタイル化"/>
        <MetricBar label="Distinctiveness / 固有性" value={v.distinctiveness} color={V2_METRICS.distinctiveness.color} sub="6ジャンル構成の全体平均との差（Jensen–Shannon divergence）"/>
        <MetricBar label="Quality / 質" value={v.quality} color={V2_METRICS.quality.color} sub="既存T-Scoreの質を10エリア内パーセンタイル化"/>
      </div>
      <div className="panel">
        <div className="panelTitle">CULTURE DNA / LOCATION QUOTIENT</div>
        <DnaBars area={area}/>
      </div>
    </div>
    <div className="insightBox">
      <div className="panelTitle">IMPLICATION</div>
      <div className="insightText">{narrative(area)}</div>
    </div>
    <div className="pendingGrid">
      <div className="pendingCard"><div className="pendingLabel">DYNAMISM</div><div className="pendingValue">DATA PENDING</div><div className="micro muted">イベント件数・新規開業・POP-UP等の時系列データを接続後に算出</div></div>
      <div className="pendingCard"><div className="pendingLabel">MOMENTUM</div><div className="pendingValue">DATA PENDING</div><div className="micro muted">前年比・3年変化率を接続後、Rising / Stable / Decliningを判定</div></div>
    </div>
  </div>;
}

function Methodology() {
  return <div className="methodGrid">
    <div className="panel"><div className="panelTitle">V2の考え方</div><p>総合ランキングだけでなく、<b>「何が強いか」「何が固有か」</b>を分けて見るためのMVPです。現行ファイルに存在する静的データだけで再計算しており、時系列データを捏造していません。</p></div>
    <div className="panel"><div className="panelTitle">Culture Vitality</div><p className="mono formula">45% Density + 30% Distinctiveness + 25% Quality</p><p>3指標は10エリア内で0–100パーセンタイル化。現時点の文化生態系の厚みを比較するための暫定総合値です。</p></div>
    <div className="panel"><div className="panelTitle">Distinctiveness</div><p>各エリアの6ジャンル構成と、10エリア全体のジャンル構成との差をJensen–Shannon divergenceで計測。ランキングを0–100化しています。</p></div>
    <div className="panel"><div className="panelTitle">Culture DNA</div><p>Location Quotient（LQ）で表示。1.00×を全体平均とし、1.50×ならそのジャンルが全体平均の1.5倍の構成比を持つことを示します。</p></div>
    <div className="panel wide"><div className="panelTitle">NEXT DATA LAYER</div><div className="nextSteps"><span>Dynamism：イベント / POP-UP / 新規開業</span><span>Momentum：前年差 / 3年変化</span><span>Sustainability：閉店 / チェーン化 / 賃料上昇</span><span>Embeddedness：回遊 / 滞在 / リピート</span></div></div>
  </div>;
}

export default function App(){
  const [selected,setSelected]=useState("原宿");
  const [metric,setMetric]=useState("vitality");
  const [view,setView]=useState("diagnosis");
  return <div className="app">
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;600;700&family=DM+Mono:wght@300;400;500&display=swap');
      :root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#06070b;color:#fff;font-family:'Noto Sans JP',sans-serif}.mono{font-family:'DM Mono',monospace}.muted{color:rgba(255,255,255,.42)}
      button{font-family:inherit}.app{min-height:100vh;background:radial-gradient(circle at 70% 0%,rgba(232,200,100,.06),transparent 32%),#06070b;padding:24px}.shell{max-width:1380px;margin:0 auto}
      .header{display:flex;justify-content:space-between;gap:28px;align-items:flex-end;margin-bottom:18px}.eyebrow{font:500 9px 'DM Mono',monospace;letter-spacing:.24em;color:rgba(255,255,255,.28);margin-bottom:8px}.header h1{margin:0;font-size:clamp(26px,4vw,46px);letter-spacing:.035em}.header p{max-width:760px;margin:8px 0 0;color:rgba(255,255,255,.46);font-size:11px;line-height:1.8}.viewTabs{display:flex;gap:4px;padding:4px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.07);border-radius:5px}.viewTabs button,.metricTabs button{border:1px solid transparent;background:transparent;color:rgba(255,255,255,.42);padding:7px 12px;border-radius:3px;cursor:pointer;font-size:10px}.viewTabs button.active{background:rgba(232,200,100,.1);border-color:rgba(232,200,100,.35);color:#E8C864}
      .heroGrid{display:grid;grid-template-columns:330px 1fr;gap:12px;align-items:stretch}.sidebar,.mapCard,.detailCard,.panel{background:rgba(255,255,255,.018);border:1px solid rgba(255,255,255,.07);border-radius:6px}.sidebar{padding:14px;min-height:650px}.sidebarHead{display:flex;justify-content:space-between;align-items:end;margin-bottom:10px}.panelTitle{font:500 9px 'DM Mono',monospace;letter-spacing:.16em;color:rgba(255,255,255,.34);margin-bottom:12px}.areaList{display:flex;flex-direction:column;gap:4px}.areaRow{width:100%;display:flex;align-items:center;gap:10px;text-align:left;border:1px solid transparent;background:transparent;color:#fff;padding:10px;border-radius:4px;cursor:pointer}.areaRow:hover{background:rgba(255,255,255,.03)}.areaRow.active{background:rgba(232,200,100,.055);border-color:rgba(232,200,100,.32)}.rank{width:24px;font-size:10px;color:rgba(255,255,255,.27)}.areaRowMain{flex:1;min-width:0}.areaNameLine{display:flex;align-items:center;gap:7px;margin-bottom:3px}.areaName{font-weight:700;font-size:13px}.typePill{font:500 8px 'DM Mono',monospace;border:1px solid;padding:1px 5px;border-radius:3px}.micro{font-size:9px;line-height:1.55}.areaScore{font-size:20px;color:#E8C864}.mapCard{padding:12px;min-height:650px}.mapTop{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:10px}.metricTabs{display:flex;gap:4px;flex-wrap:wrap}.metricTabs button.active{background:rgba(255,255,255,.06)}.mapWrap{height:590px;position:relative;border-radius:4px;overflow:hidden;border:1px solid rgba(255,255,255,.07)}.mapLegend{position:absolute;z-index:500;left:12px;bottom:12px;width:150px;background:rgba(6,7,11,.88);border:1px solid rgba(255,255,255,.1);padding:9px;border-radius:4px;backdrop-filter:blur(8px)}.legendScale{height:5px;border-radius:4px;margin:5px 0}.legendNums{display:flex;justify-content:space-between;font-size:8px;color:rgba(255,255,255,.35)}
      .detailCard{margin-top:12px;padding:22px}.detailHead{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.detailHead h2{margin:0;font-size:30px}.detailTagline{margin-top:5px;font-size:11px;color:#E8C864}.vitalBlock{text-align:right}.vitalNum{font-size:58px;line-height:.95;color:#E8C864}.typeBanner{margin:16px 0;padding:10px 12px;border:1px solid;border-radius:4px;display:flex;justify-content:space-between;gap:12px;align-items:center;font-size:11px}.detailGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.panel{padding:16px}.metricBar{margin-bottom:14px}.metricBarTop{display:flex;justify-content:space-between;font-size:11px;margin-bottom:5px}.track{height:4px;background:rgba(255,255,255,.06);border-radius:3px;overflow:hidden}.fill{height:100%;border-radius:3px}.metricBar .micro{margin-top:4px}.dnaBars{display:flex;flex-direction:column;gap:8px}.dnaRow{display:grid;grid-template-columns:78px 1fr 44px;gap:8px;align-items:center}.dnaLabel{display:flex;gap:6px;align-items:center;font-size:10px}.dot{width:6px;height:6px;border-radius:50%;display:inline-block}.dnaTrack{height:5px;background:rgba(255,255,255,.06);border-radius:3px;overflow:hidden}.dnaFill{height:100%;border-radius:3px}.dnaVal{text-align:right;font-size:9px}.insightBox{margin-top:10px;padding:16px;border-left:2px solid #E8C864;background:rgba(232,200,100,.035)}.insightText{font-size:13px;line-height:1.9;max-width:920px}.pendingGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.pendingCard{padding:14px;border:1px dashed rgba(255,255,255,.12);border-radius:4px}.pendingLabel{font:500 9px 'DM Mono',monospace;color:rgba(255,255,255,.35);letter-spacing:.15em}.pendingValue{font:500 14px 'DM Mono',monospace;color:rgba(255,255,255,.55);margin:5px 0}
      .spotFilters{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:12px 0}.chip{display:flex;align-items:center;gap:5px;background:transparent;border:1px solid;padding:5px 9px;border-radius:3px;cursor:pointer;font-size:9px}.spotMap{height:600px;border-radius:5px;overflow:hidden;border:1px solid rgba(255,255,255,.07)}
      .methodGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.methodGrid .panel{font-size:12px;line-height:1.85}.methodGrid .panel p{margin:0;color:rgba(255,255,255,.62)}.methodGrid .wide{grid-column:1/-1}.formula{color:#E8C864!important;font-size:13px;margin-bottom:8px!important}.nextSteps{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.nextSteps span{border:1px solid rgba(255,255,255,.08);border-radius:3px;padding:9px;font-size:10px;color:rgba(255,255,255,.55)}
      .leaflet-container{background:#111}.leaflet-popup-content-wrapper{background:#111316;color:#fff;border:1px solid rgba(255,255,255,.1)}.leaflet-popup-tip{background:#111316}.leaflet-control-attribution{font-size:8px!important;background:rgba(255,255,255,.72)!important}::-webkit-scrollbar{width:4px;height:4px}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:4px}
      @media(max-width:900px){.app{padding:14px}.header{align-items:flex-start;flex-direction:column}.heroGrid{grid-template-columns:1fr}.sidebar{min-height:auto}.areaList{display:grid;grid-template-columns:1fr 1fr}.mapCard{min-height:auto}.mapWrap{height:520px}.detailGrid,.pendingGrid,.methodGrid{grid-template-columns:1fr}.methodGrid .wide{grid-column:auto}.nextSteps{grid-template-columns:1fr 1fr}.typeBanner{align-items:flex-start;flex-direction:column}}
      @media(max-width:560px){.areaList{grid-template-columns:1fr}.mapWrap,.spotMap{height:460px}.detailHead{flex-direction:column}.vitalBlock{text-align:left}.nextSteps{grid-template-columns:1fr}.header h1{font-size:30px}.metricTabs button{padding:6px 8px}.detailCard{padding:16px}}
    `}</style>
    <div className="shell">
      <header className="header">
        <div><div className="eyebrow">TOKYO CULTURAL VITALITY MAP / V2 PROTOTYPE</div><h1>東京カルチャースコア V2</h1><p>「カルチャーの強い街ランキング」から、文化生態系の構造を読む地図へ。現行の10エリア・6ジャンル・スポットデータを再利用し、集積性・固有性・質とCulture DNAを再計算。</p></div>
        <div className="viewTabs">
          {[['diagnosis','DIAGNOSIS'],['spots','SPOTS'],['method','METHOD']].map(([id,l])=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}>{l}</button>)}
        </div>
      </header>
      {view==='diagnosis' && <>
        <div className="heroGrid">
          <aside className="sidebar"><div className="sidebarHead"><div><div className="panelTitle" style={{marginBottom:3}}>AREA RANKING</div><div className="micro muted">current-data MVP</div></div><div className="mono micro muted">VITALITY</div></div><AreaList selected={selected} onSelect={setSelected}/></aside>
          <section className="mapCard"><div className="mapTop"><div><div className="panelTitle" style={{marginBottom:3}}>TOKYO / 10 AREAS</div><div className="micro muted">円をクリックしてエリア診断</div></div><div className="metricTabs">{Object.entries(V2_METRICS).map(([id,m])=><button key={id} className={metric===id?'active':''} onClick={()=>setMetric(id)} style={{color:metric===id?m.color:'rgba(255,255,255,.42)',borderColor:metric===id?`${m.color}45`:'transparent'}}>{m.jp}</button>)}</div></div><OverviewMap selected={selected} onSelect={setSelected} metric={metric}/></section>
        </div>
        <AreaDetail area={selected}/>
      </>}
      {view==='spots' && <div className="detailCard"><div className="detailHead"><div><div className="eyebrow">CULTURE SPOTS / 500M RADIUS</div><h2 style={{margin:0}}>{selected}</h2></div><select value={selected} onChange={e=>setSelected(e.target.value)} style={{background:'#111316',color:'#fff',border:'1px solid rgba(255,255,255,.12)',padding:'7px 10px',borderRadius:4}}>{AREAS.map(a=><option key={a}>{a}</option>)}</select></div><CultureSpotMap area={selected}/></div>}
      {view==='method' && <Methodology/>}
    </div>
  </div>;
}
